function mergeLocale(
  base: Record<string, string>,
  ov: Record<string, string> | undefined
): Record<string, string> {
  const out: Record<string, string> = {};
  for (const key of Object.keys(base)) {
    out[key] = ov?.[key] ?? base[key]!;
  }
  return out;
}

