    "faq.title": "Häufig gestellte Fragen",
    "faq.free.q": "Ist dieses Werkzeug kostenlos?",
    "faq.free.a": "Ja, alle ZapFile-Werkzeuge sind völlig kostenlos ohne versteckte Kosten oder Abonnements.",
    "faq.safe.q": "Sind meine Daten sicher?",
    "faq.safe.a": "Absolut. Alle Verarbeitungen finden direkt in deinem Browser statt. Deine Dateien werden niemals auf einen Server hochgeladen.",
    "faq.account.q": "Muss ich ein Konto erstellen?",
    "faq.account.a": "Nein. ZapFile erfordert keine Registrierung, Anmeldung oder Kontoerstellung.",
    "faq.offline.q": "Funktioniert dieses Werkzeug offline?",
    "faq.offline.a": "Die meisten Werkzeuge funktionieren nach dem ersten Laden offline. ZapFile ist eine Progressive Web App, die du installieren kannst.",
    "faq.mobile.q": "Kann ich es auf dem Handy nutzen?",
    "faq.mobile.a": "Ja! Alle Werkzeuge sind vollständig responsiv und funktionieren auf Mobilgeräten.",
    "faq.formats.q": "Welche Formate werden unterstützt?",
    "faq.formats.a": "Unterstützte Formate sind auf jeder Werkzeugseite aufgeführt. Wir unterstützen alle gängigen Dateiformate.",
    "faq.filesize.q": "Was ist die maximale Dateigröße?",
    "faq.filesize.a": "Da die Verarbeitung in deinem Browser stattfindet, hängt die Grenze vom Arbeitsspeicher deines Geräts ab. Die meisten Dateien bis 500 MB funktionieren problemlos.",
    "faq.slow.q": "Warum ist die Verarbeitung langsam?",
    "faq.slow.a": "Schwere Aufgaben wie Videoverarbeitung laufen in deinem Browser über WebAssembly. Die Leistung hängt von deinem Gerät ab.",
